// The lattice of common multiples of 12 and 18 on a number line.
// Two-argument size() fixes the output box, so the declared 8/3 is exact.
size(320,120);
pair A=(-2,0), B=(74,0);
draw(A--B,Arrow);
label("$0$",(0,-0.75),S);
for (int k = 1; k <= 6; ++k) {
  draw((12*k,-0.14)--(12*k,0.14),gray);
}
label("$12$",(12,-0.75),S);
label("$36$",(36,-0.75),S);
label("$60$",(60,-0.75),S);
dot((12,0),2+2.5pt);
dot((24,0),2+2.5pt);
dot((36,0),2+3.5pt);
dot((48,0),2+2.5pt);
dot((60,0),2+2.5pt);
label("$\\operatorname{lcm}$",(36,0.85),N);
label("common multiples of $12$ and $18$",(36,-1.5),N);
